#!/bin/bash
# scratch: stage B2 of the t22 card (student_frames all) through trainsuite start (it composes the config with the split resolved and calls run.py with the card);
# --go starts it detached, so this script then waits until the launcher of t22.B2_s0 is gone (window_gate.py needs a command that lives as long as the job).
cd /mnt/c/Auto-research/autoresearch || exit 1
export AR_PROJECT=../bev_fusion
HYP="t22 refinement C, stage B2 (card experiments/t22_student_encoder, 'Refinement C' and 'Gate C0 result'): the same distilled EfficientViT-B1 student as in t22.B_s0 also makes the OLDER frame of the t21 P4 pair (model.student_frames all: its image from data/cache/img_front/sweeps, under no_grad), so the pair has one source in training and in the stream; everything else as t22.B_s0 (warm start t20.base_s0, 1500 steps, lr 1e-4, student 1e-5, distillation anchor on the current frame). Gate C0 with frozen weights closed the static-cell velocity excess (0.3168 -> 0.1833, control 0.2172) and lowered maps and boxes by 0.03 - 0.07; the fine-tune is to bring maps and boxes back inside the control margin"
PRED="VAL 1000 frames, dt 0, against t21.pair4_s0 (same control numbers and margins as t22.B_s0; written in the card before gate C0): static-cell velocity EPE within +0.04 of the control (stage B: +0.083), moving-centre EPE within +0.05 (stage B: +0.052), mAP of the fusion area within -0.012 (stage B: -0.0127), the other guards as in stage B, image side at most 0.5 of the teachers' time (0.37 fp32). Added after gate C0, not part of the rule: if the fine-tune recovers the same share of the loss as in stage B (about 60 % of the mAP loss), mAP of the fusion area ends near -0.04 and the guards fail; my estimate that this run reaches STAND-IN is about 10 %"
RULE="by hand: composed from the card (section 1, decision rule), one seed, the rule of t22.B_s0 unchanged: STAND-IN candidate when every guard is not below the control by more than m (point estimate and the lower end of the interval not beyond 2 m) and the cost row holds -> seed twin of student and control before any adoption (one seed never gives KEEP); BETTER when a map or line guard exceeds +m with the interval excluding 0; CUT when a guard is below the control by more than 2 m with the interval entirely below -m; INCONCLUSIVE when an interval straddles a margin -> a second seed"
python3 -m trainsuite start ../bev_fusion/training/configs/t22_B2_s0.json --id t22.B2_s0 --hyp "$HYP" --pred "$PRED" --rule "$RULE" --go --wait 20 2>&1 | cut -c1-300
echo "$(date +%H:%M:%S) launched; waiting for the launcher of t22.B2_s0 to end"
sleep 60
while ps -eo args | grep -q "[r]un.py --id t22.B2_s0 "; do sleep 30; done
echo "$(date +%H:%M:%S) launcher of t22.B2_s0 is gone"
